    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int m = Integer.parseInt(st.nextToken());
        List<String[]> paths = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            String from = st.nextToken();
            String to = st.nextToken();
            paths.add(new String[]{from, to});
        }
        Map<String, List<String>> res = getRoutes(paths);
        StringBuilder sb = new StringBuilder();
        for (String origin : new TreeSet<>(res.keySet())) {
            List<String> dests = new ArrayList<>(res.get(origin));
            Collections.sort(dests);
            sb.append(origin).append(":");
            for (String d : dests) sb.append(" ").append(d);
            sb.append("\n");
        }
        System.out.print(sb);
    }
}
